import 'dart:async';
import 'dart:convert';
import 'dart:io';

import 'api_client.dart';

/// The Reverb websocket uses the Pusher v7 wire protocol.
/// Private channel signatures are generated by Laravel Sanctum.
class RealtimeSubscription {
  RealtimeSubscription({
    required this.api,
    required this.channel,
    required this.onMessageCreated,
  });

  final ApiClient api;
  final String channel;
  final void Function() onMessageCreated;

  static const _socketHost = String.fromEnvironment('REVERB_WS_URL');
  static const _appKey = String.fromEnvironment('REVERB_APP_KEY');

  WebSocket? _socket;
  StreamSubscription<dynamic>? _events;
  Timer? _retry;
  bool _closed = false;
  bool _connecting = false;

  void start() {
    if (_socketHost.isEmpty || _appKey.isEmpty) return;
    _connect();
  }

  Future<void> _connect() async {
    if (_closed || _connecting) return;
    _connecting = true;
    try {
      final base = Uri.parse(_socketHost);
      if (base.scheme != 'wss' || base.host.isEmpty) {
        throw const FormatException('REVERB_WS_URL must be a wss URL');
      }
      final uri = base.replace(
        path: '/app/' + Uri.encodeComponent(_appKey),
        queryParameters: {
          'protocol': '7',
          'client': 'dilemin-flutter',
          'version': '1.0',
        },
      );
      final socket = await WebSocket.connect(uri.toString())
          .timeout(const Duration(seconds: 10));
      if (_closed) {
        await socket.close();
        return;
      }
      _socket = socket;
      _events = socket.listen(
        (raw) => _handle(raw),
        onDone: _reconnect,
        onError: (_) => _reconnect(),
        cancelOnError: true,
      );
    } catch (_) {
      _scheduleReconnect();
    } finally {
      _connecting = false;
    }
  }

  Future<void> _handle(dynamic raw) async {
    try {
      final packet = jsonDecode(raw.toString());
      if (packet is! Map<String, dynamic>) return;
      final event = packet['event'];
      if (event == 'pusher:connection_established') {
        final data = packet['data'] is String
            ? jsonDecode(packet['data'] as String)
            : packet['data'];
        if (data is! Map || data['socket_id'] is! String) return;
        final signature = await api.authorizeBroadcast(
          socketId: data['socket_id'] as String,
          channelName: 'private-$channel',
        );
        if (_closed || _socket?.readyState != WebSocket.open) return;
        _socket?.add(jsonEncode({
          'event': 'pusher:subscribe',
          'data': {'channel': 'private-$channel', 'auth': signature},
        }));
      } else if (event == 'message.created') {
        onMessageCreated();
      } else if (event == 'pusher:error' || event == 'pusher:subscription_error') {
        _reconnect();
      }
    } catch (_) {
      _reconnect();
    }
  }

  void _reconnect() {
    _events?.cancel();
    _events = null;
    _socket?.close();
    _socket = null;
    _scheduleReconnect();
  }

  void _scheduleReconnect() {
    if (_closed || _retry != null) return;
    _retry = Timer(const Duration(seconds: 15), () {
      _retry = null;
      _connect();
    });
  }

  void dispose() {
    _closed = true;
    _retry?.cancel();
    _retry = null;
    _events?.cancel();
    _socket?.close();
    _socket = null;
  }
}
